        static void TerrainFeatures(Transform t,int biome,System.Random random,int variant)
        {
            // Connected roads and capped waterways are generated by the AA PathNetwork wrapper.
            if((biome==0||biome==3)&&variant==0)
            {
                var bridge=Root("Bridge",t).transform;
                for(int i=0;i<10;i++) Cube(bridge,"BridgePlank",new Vector3(0,.17f,6.3f+i*.38f),new Vector3(3.4f,.22f,.34f),biome==0?Hex("A7794D"):Hex("A39B98"));
                for(int s=-1;s<=1;s+=2)
                {
                    for(int i=0;i<3;i++) Cube(bridge,"BridgePost",new Vector3(s*1.6f,.55f,6.4f+i*1.65f),new Vector3(.16f,.9f,.16f),biome==0?Brown:Hex("615663"));
                    Tube(bridge,"BridgeRail",new Vector3(s*1.6f,.94f,6.3f),new Vector3(s*1.6f,.94f,9.9f),.065f,biome==0?Brown:Hex("615663"));
                }
                var bridgeCollider=bridge.gameObject.AddComponent<BoxCollider>();bridgeCollider.center=new Vector3(0,.14f,8);bridgeCollider.size=new Vector3(3.3f,.28f,3.9f);
                if(biome==0)
