                }
                else
                {
                    // A cooled tongue meets the lava bank; the bridge and central road stay clear.
                    for(int i=0;i<5;i++)
                    {
                        Vector3 p=new Vector3(-12+i*1.25f,.1f,4.2f+Mathf.Sin(i*.55f)*.35f);
                        GroundRock(t,"LavaBankShelf",p,new Vector3(4.4f-i*.45f,.28f,2.8f),i%2==0?Hex("544E60"):Hex("685B6A"),i+112);
                        Tube(t,"BankCoolingSeam",p+new Vector3(-.6f,.17f,.7f),p+new Vector3(.8f,.17f,.5f),.025f,Hex("BE8368"));
                    }
                }
            }
            if(biome==0&&variant>0)
            {
                if(variant==1)
                {
                    var outcrop=Root("ReliefMossyBluff",t).transform;outcrop.localPosition=new Vector3(-9,0,8);
                    for(int i=0;i<3;i++)
                    {
                        float h=3.0f-i*.65f;Vector3 p=new Vector3(i*2.5f,h*.5f,i*.5f);
                        var rock=Rock(outcrop,"WoodlandStone",p,new Vector3(5.0f,h,4.8f),i%2==0?Hex("7B9484"):Hex("92A18D"),i+32);
                        rock.transform.localEulerAngles=new Vector3(0,i*37,0);rock.AddComponent<MeshCollider>().sharedMesh=rock.GetComponent<MeshFilter>().sharedMesh;
                        var moss=Rock(outcrop,"MossCap",p+Vector3.up*h*.40f,new Vector3(4.1f,.6f,3.9f),i%2==0?Hex("78A862"):Hex("98B96C"),i+32);moss.transform.localEulerAngles=new Vector3(0,i*37,0);
                        for(int j=0;j<3;j++)Sphere(outcrop,"BluffFlowers",p+new Vector3((j-1)*.4f,h*.48f,.4f),new Vector3(.19f,.13f,.19f),Cream);
                    }
                }
                for(int i=0;i<(variant==2?4:2);i++)Dune(t,new Vector3(i%2==0?-10:10,-.05f,i<2?-10:10),new Vector3(9,1.1f+i*.10f,7),i%2==0?Hex("739D55"):Hex("7CA55C"));
                for(int i=0;i<(variant==1?2:5);i++)
                {
                    Vector3 p=new Vector3((i%2==0?-1:1)*(7+(float)random.NextDouble()*5),0,-12+(float)random.NextDouble()*24);
                    Tube(t,"FallenLog",p+new Vector3(-1.8f,.3f,0),p+new Vector3(1.7f,.3f,.6f),.30f,Brown);
                    for(int j=0;j<4;j++)Sphere(t,"LogMoss",p+new Vector3((j-1.5f)*.7f,.52f,.2f),new Vector3(.65f,.19f,.48f),Hex("4F8C68"));
                }
                for(int i=0;i<18;i++){Vector3 p=new Vector3((float)random.NextDouble()*26-13,.03f,(float)random.NextDouble()*26-13);if(Mathf.Abs(p.x)<3||Mathf.Abs(p.z)<3)continue;Part(t,"WildflowerPatch",PrimitiveType.Cylinder,p,new Vector3(1.3f,.005f,.9f),Hex("8AB866"));for(int j=0;j<5;j++){Vector3 q=p+new Vector3(Mathf.Sin(j*2.4f)*.4f,.15f,Mathf.Cos(j*2.4f)*.4f);Sphere(t,"Wildflowers",q,new Vector3(.11f,.08f,.11f),i%2==0?Gold:Cream);}}
            }
            if(biome==1)
            {
                // The oasis leaves its northeast bank level for an actual road-connected ruin.
                for(int i=0;i<(variant==0?2:variant==2?1:4);i++)
                {
                    Vector3 p=new Vector3((i%2==0?-1:1)*(8+(float)random.NextDouble()*2),-.13f,(i<2?-1:1)*(8+(float)random.NextDouble()*2));
                    if(Vector3.Distance(p,new Vector3(-9,0,8))<6)continue;
                    Dune(t,p,new Vector3(9+(float)random.NextDouble(),2.1f+i*.18f+variant*.18f,6.3f),i%2==0?Hex("E8C58A"):Hex("CFA467"));
                }
                if(variant==2)
