                    for(int i=0;i<2;i++)
                    {
                        Vector3 p=new Vector3(i==0?-9:9,1.5f,i==0?9:-9);
                        var relief=Root("ReliefButte"+i,t).transform;relief.localPosition=p;
                        var mesa=Rock(relief,"SandstoneButte",Vector3.zero,new Vector3(7.8f,3.8f,6.8f),Hex("BD875A"),i+21);
                        mesa.transform.localEulerAngles=new Vector3(0,i*137,0);
                        mesa.AddComponent<MeshCollider>().sharedMesh=mesa.GetComponent<MeshFilter>().sharedMesh;
                        var crown=Rock(relief,"ErodedCrown",Vector3.up*1.45f,new Vector3(5.8f,1.0f,5.0f),Hex("E0B47A"),i+21);crown.transform.localEulerAngles=new Vector3(0,i*137,0);
                        for(int j=0;j<3;j++)Rock(t,"TalusStone",p+new Vector3(-2+j*2,-1.2f,2.4f),new Vector3(1.4f,1.0f,1.1f),Hex("CEA16B"),i+j);
